import Foundation
import RFCCorpusKit
import RFCKit
import Testing

/// `PatchWriter`, over a small document written by hand in the shape of the
/// converter's output, so no RFC text is added: each test edits a copy of it and
/// checks the patch written for the edit (#742). Every patch is proven before it is
/// returned, so each test also shows that its patch gives the edited copy.
@Suite("Writing a patch")
struct PatchWriterTests {
  private static let original = """
    <?xml version='1.0' encoding='utf-8'?>
    <!-- Generated by rfc-reader corpus-build from rfc9999.txt. Structure recovered heuristically from the plain-text RFC; the text itself is unchanged. -->
    <rfc version="3" xml:lang="en">
      <front>
        <title>Example Exchange</title>
        <date month="5" year="1990"/>
      </front>
      <middle>
        <section anchor="preamble" numbered="false">
          <name></name>
          <artwork>
    Example Header
    </artwork>
          <t>The opening paragraph.</t>
        </section>
        <section anchor="name-overview" numbered="false">
          <name>Overview</name>
          <t>A first paragraph of the overview.</t>
          <t>A second paragraph of the overview.</t>
          <t>Use <em>this</em> form.</t>
          <t>A closing note.</t>
        </section>
      </middle>
    </rfc>

    """

  /// The patch for the original with each of `edits` made to it.
  private static func patch(_ edits: [(String, String)]) throws -> String {
    var edited = original
    for (old, new) in edits {
      #expect(edited.contains(old), "\(old)")
      edited = edited.replacingOccurrences(of: old, with: new)
    }
    return try PatchWriter.patch(
      original: Data(original.utf8), edited: Data(edited.utf8), name: "rfc9999.xml")
  }

  /// The operations of `patch`, one per line, without the comments before them.
  private static func operations(_ patch: String) -> [String] {
    patch.split(separator: "\n").map { $0.trimmingCharacters(in: .whitespaces) }
      .filter {
        !$0.hasPrefix("<?xml") && !$0.hasPrefix("<!--") && $0 != "<diff>" && $0 != "</diff>"
      }
  }

  private static func failure(_ edits: [(String, String)]) throws -> String {
    try #require(throws: PatchWriter.Failure.self) { try patch(edits) }.description
  }

  @Test func `a removed element is selected by its anchored parent and its first words`() throws {
    let patch = try Self.patch([("      <artwork>\nExample Header\n</artwork>\n", "")])
    #expect(
      Self.operations(patch) == [
        #"<remove sel="//section[@anchor='preamble']/artwork[starts-with(normalize-space(), 'Example')]"/>"#
      ])
  }

  @Test func `an element added after a sibling is selected by the sibling's first words`() throws {
    let patch = try Self.patch([
      (
        "<t>A first paragraph of the overview.</t>",
        "<t>A first paragraph of the overview.</t>\n<t>An added paragraph.</t>"
      )
    ])
    #expect(
      Self.operations(patch) == [
        #"<add sel="//section[@anchor='name-overview']/t[starts-with(normalize-space(), 'A first')]" pos="after"><t>An added paragraph.</t></add>"#
      ])
  }

  @Test func `an element added ahead of every sibling goes before the first`() throws {
    let patch = try Self.patch([
      (
        "<middle>\n",
        "<middle>\n<section anchor=\"name-added\" numbered=\"false\"><name>Added</name></section>\n"
      )
    ])
    #expect(
      Self.operations(patch) == [
        #"<add sel="//section[@anchor='preamble']" pos="before"><section anchor="name-added" numbered="false"><name>Added</name></section></add>"#
      ])
  }

  @Test func `an attribute is added or replaced on its element`() throws {
    let patch = try Self.patch([
      (#"<date month="5" year="1990"/>"#, #"<date day="2" month="5" year="1991"/>"#)
    ])
    #expect(
      Self.operations(patch) == [
        #"<add sel="/rfc/front/date" type="@day">2</add>"#,
        #"<replace sel="/rfc/front/date/@year">1991</replace>"#,
      ])
  }

  @Test func `changed text replaces the element that holds it`() throws {
    let patch = try Self.patch([("A closing note.", "A closing remark.")])
    #expect(
      Self.operations(patch) == [
        #"<replace sel="//section[@anchor='name-overview']/t[starts-with(normalize-space(), 'A closing')]"><t>A closing remark.</t></replace>"#
      ])
  }

  @Test func `changed text in an inline element replaces only that element`() throws {
    let patch = try Self.patch([("<em>this</em>", "<em>that</em>")])
    #expect(
      Self.operations(patch) == [
        #"<replace sel="//section[@anchor='name-overview']/t[starts-with(normalize-space(), 'Use')]/em[starts-with(normalize-space(), 'this')]"><em>that</em></replace>"#
      ])
  }

  /// RFC 822's patch tells two artworks that open alike apart the same way.
  @Test func `siblings that open alike are told apart by words further on`() throws {
    let artworks = """
      <artwork>
      Field Value Field Value Field Value Field Value - 1 -
      </artwork>
      <artwork>
      Field Value Field Value Field Value Field Value - 2 -
      </artwork>
      """
    var original = Self.original
    original = original.replacingOccurrences(
      of: "<t>The opening paragraph.</t>", with: "<t>The opening paragraph.</t>\n\(artworks)")
    let edited = original.replacingOccurrences(
      of: "<artwork>\nField Value Field Value Field Value Field Value - 2 -\n</artwork>", with: "")
    let patch = try PatchWriter.patch(
      original: Data(original.utf8), edited: Data(edited.utf8), name: "rfc9999.xml")
    #expect(
      Self.operations(patch) == [
        #"<remove sel="//section[@anchor='preamble']/artwork[starts-with(normalize-space(), 'Field')][contains(normalize-space(), '2 -')]"/>"#
      ])
  }

  @Test func `an element only its position could select stops the patch`() throws {
    let header = "<artwork>\nExample Header\n</artwork>"
    let original = Self.original.replacingOccurrences(of: header, with: header + "\n" + header)
    let failure = try #require(throws: PatchWriter.Failure.self) {
      try PatchWriter.patch(
        original: Data(original.utf8), edited: Data(Self.original.utf8), name: "rfc9999.xml")
    }
    #expect(failure.description.contains("only its position"), "\(failure)")
    #expect(failure.description.contains("artwork"), "\(failure)")
  }

  @Test func `each operation is preceded by a reason to fill in`() throws {
    let patch = try Self.patch([("A closing note.", "A closing remark.")])
    #expect(
      patch == """
        <?xml version="1.0" encoding="UTF-8"?>
        <diff>
          <!-- \(PatchWriter.reasonPlaceholder) -->
          <replace sel="//section[@anchor='name-overview']/t[starts-with(normalize-space(), 'A closing')]"><t>A closing remark.</t></replace>
        </diff>

        """)
  }

  @Test func `a patch read with its reasons still to fill in fails`() throws {
    let patch = try Self.patch([("A closing note.", "A closing remark.")])
    let failure = try #require(throws: XMLPatch.Failure.self) {
      try XMLPatch(parsing: Data(patch.utf8), name: "rfc9999.xml")
    }
    #expect(failure.description.contains("TODO"), "\(failure)")
  }

  /// Laid out anew, the copy holds the same content.
  @Test func `an edited copy the same as the original has nothing to patch`() throws {
    let failure = try Self.failure([("      <t>The opening", "<t>The opening")])
    #expect(failure.contains("nothing to patch"), "\(failure)")
  }

  /// Not the closing note, the first of two siblings in the gap, which an edit in
  /// place would pair with the rewritten one.
  @Test func `a removed element beside a rewritten one is removed, and the other replaced`()
    throws
  {
    let patch = try Self.patch([
      ("<t>Use <em>this</em> form.</t>", ""), ("A closing note.", "A closing remark."),
    ])
    #expect(
      Self.operations(patch) == [
        #"<remove sel="//section[@anchor='name-overview']/t[starts-with(normalize-space(), 'Use')]"/>"#,
        #"<replace sel="//section[@anchor='name-overview']/t[starts-with(normalize-space(), 'A closing')]"><t>A closing remark.</t></replace>"#,
      ])
  }

  /// The writer puts `version="3"` back, so the patch would not give the edited copy.
  @Test func `an edit that writing the document undoes fails the proof`() throws {
    let failure = try Self.failure([(#"<rfc version="3" "#, "<rfc ")])
    #expect(failure.contains("changes nothing the model holds"), "\(failure)")
  }

  /// A patch applies to the converter's own output, which a patched document is not.
  @Test func `a patched document is refused as the original`() throws {
    let patched = Self.original.replacingOccurrences(
      of: "from rfc9999.txt.", with: "from rfc9999.txt and patched by corpus/overrides/rfc9999.xml."
    )
    let failure = try #require(throws: PatchWriter.Failure.self) {
      try PatchWriter.patch(
        original: Data(patched.utf8), edited: Data(patched.utf8), name: "rfc9999.xml")
    }
    #expect(failure.description.contains("patched"), "\(failure)")
  }
}

/// The committed patches written again: the converter's output for each document,
/// and the output with its committed patch applied as the edited copy, as a corpus
/// run applies it with the index's metadata. The patch written must give the same
/// document.
@Suite(
  "Corpus-backed: writing a patch", .enabled(if: CorpusText.isAvailable && CorpusText.hasIndex))
struct CorpusBackedPatchWriterTests {
  @Test(arguments: ["rfc5", "rfc822"])
  func `a committed patch is written again from its result`(stem: String) throws {
    let metadata = try ConversionPlan.rfcNumber(of: stem).flatMap { try CorpusText.index()[$0] }
    let text = try CorpusText.text(stem)
    let converted = try #require(
      DocumentConverter().convert(text: text, stem: stem, metadata: metadata).xml)
    let committed = try XMLPatch(
      parsing: try Data(contentsOf: OverridesTests.directory.appending(path: "\(stem).xml")),
      name: "\(stem).xml")
    let patched = try #require(
      DocumentConverter().convert(text: text, stem: stem, metadata: metadata, patch: committed).xml,
      "the committed patch applies")
    // Proven inside: the patch it returns gives the patched document.
    let written = try PatchWriter.patch(original: converted, edited: patched, name: "\(stem).xml")
    let reasons = written.components(separatedBy: PatchWriter.reasonPlaceholder).count - 1
    #expect(reasons == committed.operationCount, "\(written)")
  }
}
